function missingCookieFlags(setCookie) {
  const attributes = setCookie
    .split(";")
    .slice(1)
    .map((part) => part.trim().split("=")[0].toLowerCase());
  const required = ["Secure", "HttpOnly", "SameSite"];
  return required.filter((name) => !attributes.includes(name.toLowerCase()));
}

