function canAccess(user, record, action) {
  if (!user) return false;
  const actions = ["read", "update", "delete"];
  if (!actions.includes(action)) return false;
  if (user.role === "admin") return true;
  if (user.role === "patient") {
    return action !== "delete" && record.ownerId === user.id;
  }
  return false;
}

tests.code:
const me = { id: 7, role: "patient" };
assertEqual(canAccess(me, { ownerId: 7 }, "read"), true, "own read");
assertEqual(canAccess(me, { ownerId: 7 }, "update"), true, "own update");

const b = { id: 8, role: "patient" };
assertEqual(canAccess(b, { ownerId: 7 }, "read"), false, "other patient's record");
assertEqual(canAccess(b, { ownerId: 7 }, "update"), false, "other patient's record");
assertEqual(canAccess(b, { ownerId: 8 }, "delete"), false, "patients never delete");
assertEqual(canAccess(b, { ownerId: 8 }, "read"), true, "own read still allowed");

const admin = { id: 1, role: "admin" };
assertEqual(canAccess(admin, { ownerId: 7 }, "delete"), true, "admin delete");
assertEqual(canAccess(admin, { ownerId: 7 }, "read"), true, "admin read");
assertEqual(canAccess(null, { ownerId: 7 }, "read"), false, "nobody logged in");

assertEqual(canAccess({ id: 7, role: "guest" }, { ownerId: 7 }, "read"), false, "unknown role");
assertEqual(canAccess({ id: 1, role: "admin" }, { ownerId: 7 }, "export"), false, "unknown action, even for an admin");
assertEqual(canAccess({ id: 1, role: "admin" }, { ownerId: 7 }, "update"), true, "known action for an admin");

