function findLeaks(body) {
  const checks = [
    ["stack-trace", /^\s*at .*\(.*:\d+/m],
    ["sql", /\bselect\b[\s\S]*\bfrom\b|\binsert\s+into\b|\bupdate\b[\s\S]*\bset\b|\bdelete\s+from\b/i],
    ["version", /[A-Za-z][\w.-]*[\/ ]\d+\.\d+(\.\d+)*/],
  ];
  return checks.filter(([, pattern]) => pattern.test(body)).map(([name]) => name);
}

tests.code:
assertEqual(findLeaks('{"error":"Order not found"}'), [], "generic JSON error");
assertEqual(findLeaks("Invalid email or password"), [], "generic login error");
assertEqual(findLeaks("error in select * from users where id = 1"), ["sql"], "lower-case SQL");

assertEqual(findLeaks("Failed: INSERT INTO orders VALUES (?)"), ["sql"], "insert");
assertEqual(findLeaks("Failed: Update users Set name = ?"), ["sql"], "update");
assertEqual(findLeaks("could not delete from carts"), ["sql"], "delete");

assertEqual(findLeaks("TypeError: x is undefined\n    at handler (/app/routes/orders.js:12:5)"), ["stack-trace"], "stack trace");
assertEqual(findLeaks("Served by nginx/1.25"), ["version"], "slash version");
assertEqual(findLeaks("Powered by Express 4.17.1"), ["version"], "space version");

const body = "Express 4.17.1
SequelizeDatabaseError: syntax error
  SELECT * FROM products WHERE name LIKE '%'%'
    at Query.run (/app/node_modules/sequelize/lib/query.js:50:25)
    at next (/app/server.js:9:3)";
assertEqual(findLeaks(body), ["stack-trace", "sql", "version"], "all three");
